#pragma once

#include <stddef.h>
#include <stdint.h>

#include "ai_inference_model_data.h"

/*
 * Active TinyML model: scene-specific FOMO vehicle-centroid detector,
 * trained on frames from the actual install site (see
 * experiments/vehicle_count/README.md). The weights live in
 * ai_inference_vehicle_model.c (generated by train_fomo.py, len = 36424
 * bytes, full-int8).
 *
 * Input  [1,96,96,1] int8 luma; output [1,12,12,2] int8, channel 0 =
 * background, channel 1 = vehicle. populate_fomo_detections() turns the
 * 12x12 grid into centroid detections (up to AIOT_AI_RESULT_MAX_DETECTIONS),
 * and raw_score = best per-cell confidence drives the presence state machine
 * (so "present" == "a vehicle is in view"). When TFLM cannot load this model
 * at runtime, ai_inference.c transparently falls back to the frame-difference
 * motion detector.
 */
extern const unsigned char g_vehicle_fomo_model_data[];

static const ai_inference_model_asset_t g_ai_inference_generated_model_asset = {
    .data = g_vehicle_fomo_model_data,
    .len = 36424U,
    .tensor_arena_size = 128U * 1024U,
    .input_width = 96U,
    .input_height = 96U,
    .detection_threshold = 128U, /* int8 softmax center */
    .class_count = 1U,
    .background_index = 0U,       /* background */
    .target_class_index = 0U,     /* ignored for FOMO */
    .output_type = AI_INFERENCE_OUTPUT_FOMO,
};
